<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { allowedReturnPath } from '../domain/navigation.js'
import { router } from '../router.js'
import { state,t } from '../state.js'
import { social,loadSocial,person,socialAction } from '../social-state.js'
import { newId } from '../domain/id.js'
import ContentShell from '../components/ContentShell.vue'
import PersonAvatar from '../components/PersonAvatar.vue'
import ActionButton from '../components/ActionButton.vue'
import AppModal from '../components/AppModal.vue'
const route=useRoute(),isRequests=computed(()=>route.name==='friendRequests'),direction=ref(route.query.direction==='sent'?'sent':'received'),ignore=ref(null),commits={}
onMounted(loadSocial)
const friends=computed(()=>social.profiles.filter(p=>p.relationship?.friends&&!p.relationship.blocked)),requests=computed(()=>social.requests.filter(r=>r.direction===direction.value).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))
const pending=computed(()=>social.requests.filter(r=>r.direction==='received'&&r.status==='pending'&&!r.blocked).length)
const peer=r=>r.direction==='received'?r.senderId:r.recipientId
async function resolve(r,method){const key=r.id+':'+method;commits[key]||=newId();if(await socialAction(method,{requestId:r.id,commitId:commits[key]}))ignore.value=null}
function change(value){direction.value=value;router.replace({name:'friendRequests',query:{...route.query,direction:value}})}
const date=value=>new Intl.DateTimeFormat(state.locale,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value))
function profile(id){router.push({name:'profile',params:{id},query:{from:route.fullPath}})}
</script>
<template><ContentShell back :title="t(isRequests?'s.requests':'s.friends')" :ready="social.loaded" class="social-shell" @back="router.push(isRequests?allowedReturnPath(route.query.from,{fallback:'/friends',exact:['/friends']}):route.query.from==='/mine'?'/mine':'/chats')"><div v-if="!social.loaded" class="content-state"><p>{{ t('s.loading') }}</p><ActionButton v-if="!state.ui.busy" @click="loadSocial">{{ t('retry') }}</ActionButton></div><template v-else-if="!isRequests"><button class="social-row" @click="router.push({path:'/friend-requests',query:{from:route.fullPath}})"><img class="row-art" src="/images/p3/requests-avatar.png" alt=""/><span class="row-main"><strong>{{ t('s.requests') }}</strong><small>{{ pending }} · {{ t('s.received') }}</small></span><span v-if="pending" class="unread-badge">{{ pending }}</span></button><div v-for="p in friends" :key="p.id" class="social-row friend-row"><button class="person-link" @click="profile(p.id)"><PersonAvatar :person="p"/><span class="row-main"><strong>{{ p.displayName }}</strong><small>{{ p.aboutTranslations?.[state.locale]||p.about||t('s.noAbout') }}</small></span></button><button class="friend-chat" :aria-label="t('s.openChat')+' · '+p.displayName" @click="router.push({name:'conversation',params:{peer:p.id},query:{from:route.fullPath}})"><img src="/images/p3/chat-action.png" alt=""/></button></div><p v-if="!friends.length" class="social-empty">{{ t('s.noFriends') }}</p></template><template v-else><nav class="social-filters" :aria-label="t('s.requests')"><button v-for="key in ['received','sent']" :key="key" :aria-pressed="direction===key" @click="change(key)">{{ t('s.'+key) }}</button></nav><p v-if="!requests.length" class="social-empty">{{ t('s.noRequests') }}</p><article v-for="r in requests" :key="r.id" class="request-item"><time>{{ date(r.createdAt) }}</time><div class="request-card"><div class="request-profile"><PersonAvatar :person="person(peer(r))" :size="48"/><div><strong>{{ person(peer(r))?.displayName||'Eluva' }}</strong></div><button @click="profile(peer(r))">{{ t('s.profile') }} ›</button></div><p v-if="r.blocked">{{ t('s.blocked') }}</p><template v-else><p>{{ t(r.direction==='received'?'s.requestFrom':'s.requestTo',{name:person(peer(r))?.displayName||'Eluva'}) }}</p><p class="request-intro">{{ r.demo?t(r.direction==='received'?'s.fixtureReceived':'s.fixtureSent'):r.body }}</p><div v-if="r.direction==='received'&&r.status==='pending'" class="request-actions"><ActionButton secondary :disabled="!!state.ui.busy" @click="ignore=r">{{ t('s.ignore') }}</ActionButton><ActionButton class="purple-gradient" :busy="state.ui.busy==='social-accept'" :disabled="!!state.ui.busy" @click="resolve(r,'accept')">{{ t('s.accept') }}</ActionButton></div><p v-else class="request-status">{{ t('s.'+r.status) }}</p></template></div></article></template></ContentShell><AppModal v-if="ignore" :title="t('s.ignoreTitle')" :closable="!state.ui.busy" @close="ignore=null"><p>{{ t('s.ignoreHint') }}</p><p v-if="state.ui.error" class="error-banner" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p><template #footer><ActionButton secondary :disabled="!!state.ui.busy" @click="ignore=null">{{ t('cancel') }}</ActionButton><ActionButton :busy="!!state.ui.busy" @click="resolve(ignore,'ignore')">{{ t('s.ignore') }}</ActionButton></template></AppModal></template>
